// Rev3 unattended soak testing: a bot that plays the local pad, an automatic end of the run, and the freeze / wall-clock exits.
// Licensed under GPLv2+ like the rest of this fork. No game data; the Rev3 addresses and button bits are cited where they are used.
//
// WHAT IT DOES
//   REV3_PAD_BOT=<seed>        the LOCAL pad (hook command port 0) is generated by a bot instead of read from the controller. Netplay still
//                              exchanges it like any pad, so rollbacks and mispredictions happen naturally (the two sides run different
//                              seeds, and REV3_NETSIM adds lag). Fight pad: a pure function of (seed, port, frame) built from segments (hold
//                              a direction 8-40 frames, bursts of attack / jutsu / throw / sidestep presses, jumps, occasional idle,
//                              chakra charge, super motions). Menu pad (no fighters found): A every 48 frames, every 6th time Start.
//   REV3_NET_EXIT=match|frames:N|rounds:N   stop the emulator by itself after the match (see ExitController)
//   REV3_NET_EXIT_WAIT_S=n     seconds between that decision and the stop request (default 5)
//   REV3_NET_FREEZE_EXIT_S=n   freeze watchdog: n seconds after the freeze dump fired with no hook command, write LEAVE reason=freeze and exit
//                              with code EXIT_CODE_FREEZE (0 = off, the default)
//   REV3_NET_MAX_S=n           hard cap in wall seconds from the first hook command: stop requested, and exit code EXIT_CODE_MAX_S if that
//                              does not end the process (0 = off, the default)
//   unplanned LEAVE            with REV3_NET_EXIT set, a netplay session that ends for any reason but the other side's planned exit (a timeout, a
//                              desync, a lost link) stops the emulator after REV3_NET_EXIT_WAIT_S and the process exits with EXIT_CODE_LEFT
//                              (ExitController::NoteLeave). Before this a session that left carried on offline and the run only ended at the
//                              runner's timeout (D's soak, Oct 16: run_2 and run_6).
//
// HOW IT FITS IN
//   Pure logic (no Dolphin, no clock, no files): Rev3Rollback.cpp's DeterminismKit calls PadBotController after the pad script has had its say,
//   HandleCommand feeds ExitController, and a host-side thread in the Dolphin glue applies FreezeExitDue / MaxSecondsDue. REV3.md "Bot soak"
//   has the variables and log lines; rev3-mod tools/rollback/soak.py is the runner; Rev3BotTest.cpp the tests.
//
// DETERMINISM
//   The bot's pad is a function of (seed, port, frame) and of the mode (menu / fight) only. The generator draws from splitmix64 streams seeded
//   by (seed, port, segment index); nothing depends on call order, so a frame asked twice (a resimulation) gives the same pad.

#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <string>
#include <vector>

#include "Common/CommonTypes.h"

namespace Rev3::Bot
{
using BotPad = std::array<u8, 12>;  // one PADStatus: buttons u16 BE, stickX/Y, c-stickX/Y, triggerL/R, analogA/B, err (same as Rev3::PadBytes)
using LogFn = std::function<void(const std::string&)>;

// GameCube PADStatus button bits (Dolphin SDK pad.h; rev3-mod tools/rollback/inputs.py PAD_BITS). The hook's pad has no PAD_USE_ORIGIN bit
// (D's pad record, Oct 16: an A press reads 0x0100).
constexpr u16 BTN_LEFT = 0x0001;
constexpr u16 BTN_RIGHT = 0x0002;
constexpr u16 BTN_DOWN = 0x0004;
constexpr u16 BTN_UP = 0x0008;
constexpr u16 BTN_Z = 0x0010;
constexpr u16 BTN_R = 0x0020;
constexpr u16 BTN_L = 0x0040;
constexpr u16 BTN_A = 0x0100;
constexpr u16 BTN_B = 0x0200;
constexpr u16 BTN_X = 0x0400;
constexpr u16 BTN_Y = 0x0800;
constexpr u16 BTN_START = 0x1000;

// Rev3 controls (rev3-mod tools/rollback/inputs.py docstring and docs/findings.md "Guard in the takes"): B weak attack, A strong attack,
// X jutsu (2X / 5X = the supers), Y throw, L / R sidestep and substitution, jump = stick up, guard = hold back (there is no guard button).
// Z as the chakra charge is a GUESS (nothing in the findings says what Z does): it is one of the bot's rarest segments.
constexpr int STICK_FULL = 100;   // stick units (PADStatus std::int8_t, range +-127): a cardinal push; PADClampCircle then limits the radius to 56
constexpr int STICK_DIAG = 72;    // each axis of a diagonal push (72 * sqrt(2) = 102)
constexpr u8 TRIGGER_FULL = 0xB4;  // analog L / R together with the digital click (inputs.py TRIGGER_FULL)

// ---- the generator ----------------------------------------------------------------------------------------------------------------
enum class SegmentKind
{
  Idle,
  Move,
  Jump,
  Attack,
  Jutsu,
  Throw,
  Sidestep,
  Chakra,
  Super,
  Guard,
  Count
};
const char* SegmentKindName(SegmentKind kind);

// Share of each segment kind in percent (SegmentKind order, sums to 100). Tunable: the mix of what the bot does.
constexpr std::array<u32, static_cast<size_t>(SegmentKind::Count)> SEGMENT_WEIGHTS = {8, 30, 7, 22, 8, 5, 4, 3, 4, 9};
constexpr u32 MOVE_MIN_FRAMES = 8;   // a held direction lasts this many frames at least ...
constexpr u32 MOVE_MAX_FRAMES = 40;  // ... and this many at most (frames, 60 per second)
constexpr u32 GENERATOR_MAX_FRAME = 1u << 26;  // frames past this (about 311 hours) get a neutral pad (keeps the segment table finite)

struct PadStep
{
  u32 frames = 1;
  u16 buttons = 0;
  std::int8_t stick_x = 0;
  std::int8_t stick_y = 0;
  std::int8_t cstick_x = 0;
  std::int8_t cstick_y = 0;
  u8 trigger_l = 0;
  u8 trigger_r = 0;
};

struct Segment
{
  SegmentKind kind = SegmentKind::Idle;
  std::vector<PadStep> steps;
  u32 Length() const;  // sum of the steps' frames (at least 1)
};

// Segment `index` of the stream (seed, port): a pure function of its arguments.
Segment BuildSegment(u64 seed, u32 port, u32 index);
BotPad ToBotPad(const PadStep& step);

class PadGenerator
{
public:
  // `port` = the game port of this side (0 host, 1 guest): the two sides of a run play different streams even with the same seed.
  PadGenerator(u64 seed, u32 port);

  // The fight pad of `frame`: segments tile the frame line from frame 0; the answer does not depend on which frames were asked before.
  BotPad FightPad(u32 frame);
  SegmentKind KindAt(u32 frame);
  // The menu pad of `frame`: A pressed for MENU_PRESS_FRAMES of every MENU_PERIOD_FRAMES (start offset drawn per period), every
  // MENU_START_EVERY-th period Start instead of A.
  BotPad MenuPad(u32 frame) const;

  u64 seed() const { return m_seed; }
  u32 port() const { return m_port; }

private:
  void Ensure(u32 frame);
  u64 m_seed;
  u32 m_port;
  std::vector<u32> m_end;  // m_end[i] = first frame after segment i
  u32 m_cached_index = 0xFFFFFFFFu;
  Segment m_cached;
};

constexpr u32 MENU_PERIOD_FRAMES = 48;  // frames between two menu presses (0.8 s)
constexpr u32 MENU_PRESS_FRAMES = 6;    // frames each press is held
constexpr u32 MENU_START_EVERY = 6;     // every 6th press is Start (advances "press start" screens), the others A
constexpr u32 MENU_JITTER_FRAMES = 8;   // the press starts this many frames at most after the period began

// ---- what the bot sees of the game ------------------------------------------------------------------------------------------------
// One reading of the game at a hook call (Rev3Rollback.cpp ReadGameObs fills it from guest memory).
struct GameObs
{
  bool fighters_found = false;  // both fighters through the TEAMS chain (rbchecksum.find_fighters)
  bool health_zero = false;     // a found fighter's health (+0x28) is 0
  bool scene_valid = false;
  u32 scene_type = 0;           // *0x803C11D4: 2 = a match, 3 = menus, 6 = movie (rev3-mod tools/takes/rev3_menu.py SCENE_TYPE)
  u32 scene_sub = 0;            // *0x803C11D8
};
constexpr u32 SCENE_TYPE_ADDR = 0x803C11D4;  // rev3_menu.py SCENE_TYPE
constexpr u32 SCENE_SUB_ADDR = 0x803C11D8;   // rev3_menu.py SCENE_SUB
constexpr u32 FIGHTER_HEALTH_OFFSET = 0x28;  // rbchecksum.py "health" (u32)

// ---- the controller: script, then menus / fight ---------------------------------------------------------------------------------
class PadBotController
{
public:
  PadBotController(u64 seed, u32 port, LogFn log);

  // One hook call that is not a resimulation. `script_active`: a REV3_PAD_SCRIPT exists and `frame` is not past its last frame (the script's
  // pad is then already in the command and stays). Takeover rule (chosen and documented): the bot takes the local pad from the first call
  // with both fighters found (the script's remaining lines are ignored from then on) or, with no fighters yet, from the first call past the
  // script's end (no script: from frame 0). True and *pad filled when the bot drives this call; false: leave the pad alone.
  bool Choose(u32 frame, bool script_active, const GameObs& obs, BotPad* pad);

  bool FightFound() const { return m_latched; }
  u32 FightFrame() const { return m_fight_frame; }
  bool InFight() const { return m_in_fight; }
  PadGenerator& generator() { return m_gen; }

private:
  PadGenerator m_gen;
  LogFn m_log;
  bool m_latched = false;      // fighters were found at least once
  u32 m_fight_frame = 0;
  bool m_took_over = false;
  bool m_in_fight = false;     // the last driven call had fighters
  bool m_mode_known = false;
};

// ---- the end of the run -----------------------------------------------------------------------------------------------------------
enum class ExitKind
{
  Match,   // after the match is over (see ExitController)
  Frames,  // after N hook calls since the fight was found (the call that found it is the first)
  Rounds   // after N round KOs
};

struct ExitSpec
{
  bool enabled = false;
  ExitKind kind = ExitKind::Match;
  u32 n = 0;
};

// "match", "frames:N" (N 1..100000000), "rounds:N" (N 1..99); case and spaces ignored. An empty text is a disabled spec (true). False with
// *error otherwise.
bool ParseExitSpec(const std::string& text, ExitSpec* out, std::string* error);
std::string ExitSpecText(const ExitSpec& spec);

// All counts are hook calls that are not resimulations (60 per second of game time).
struct ExitTuning
{
  u32 wait_calls = 300;               // REV3_NET_EXIT_WAIT_S * 60: from the decision to the stop request (calls)
  u32 ko_debounce_calls = 30;         // a fighter at health 0 for this long (after both were healthy) is a KO (calls); filters mispredicted frames
  u32 scene_away_calls = 60;          // the scene type differs from the fight's for this long (calls) after enough KOs: the results screen
  u32 lost_calls = 600;               // the fighters are not found for this long (calls) after enough KOs: the match is over
  u32 idle_after_ko_calls = 1800;     // no new round (both fighters healthy again) this long after a KO (calls, 30 s): the match is over
  u32 min_rounds_for_scene_rule = 2;  // scene / lost rules need this many KOs (Rev3's rounds per match are not known; the idle rule needs 1)
};
constexpr u32 EXIT_WAIT_DEFAULT_S = 5;  // REV3_NET_EXIT_WAIT_S default (seconds)
constexpr u32 EXIT_CALLS_PER_SECOND = 60;

struct ExitStep
{
  bool stop = false;  // request the emulator to stop now
  bool left = false;  // the stop is the one NoteLeave decided (the session left unplanned): the process exits with EXIT_CODE_LEFT
  std::string reason; // "match: ...", "frames:N", "rounds:N", "net session left: <why>"
};

// Watches the game from the CPU thread (one call per hook call that is not a resimulation) and decides when the run is over:
//   match   needs the fight found and at least one KO, then ends on the first of: (scene) the scene type differs from the fight's for
//           scene_away_calls, (lost) no fighters for lost_calls -- both only from min_rounds_for_scene_rule KOs on --, (idle) no new
//           round for idle_after_ko_calls. A KO = a fighter at health 0 for ko_debounce_calls, counted once per round (both fighters must
//           have been healthy before it: the loading screen's zeros are not a KO).
//   frames:N  N calls after the fight was found.     rounds:N  the N-th KO.
// The stop is requested wait_calls after the decision.
class ExitController
{
public:
  ExitController(const ExitSpec& spec, const ExitTuning& tuning, LogFn log);
  ExitStep OnCall(u32 frame, const GameObs& obs);
  // The net session left for a reason that is not a planned exit of either side: the run is over, whatever the game is doing. Decides like a
  // planned exit (the stop follows wait_calls later) but marks the step `left`. False (and nothing happens) when disabled or already decided.
  bool NoteLeave(u32 frame, const std::string& why);

  u32 Kos() const { return m_ko; }
  bool Decided() const { return m_decided; }
  bool FightSeen() const { return m_fight_seen; }
  u32 FightCalls() const { return m_fight_seen ? m_calls - m_fight_start_call + 1 : 0; }  // calls since the fight was found, the first included

private:
  void Decide(u32 frame, const std::string& reason);
  ExitSpec m_spec;
  ExitTuning m_tuning;
  LogFn m_log;
  u32 m_calls = 0;
  bool m_fight_seen = false;
  u32 m_fight_start_call = 0;
  bool m_scene_known = false;
  u32 m_fight_scene = 0;
  bool m_healthy_seen = false;  // both fighters healthy since the last KO
  u32 m_zero_run = 0;
  u32 m_ko = 0;
  u32 m_last_ko_call = 0;
  u32 m_away_run = 0;
  u32 m_lost_run = 0;
  bool m_decided = false;
  bool m_left = false;  // the decision is NoteLeave's
  u32 m_decide_call = 0;
  std::string m_reason;
  bool m_stop_sent = false;
};

// ---- host-side exits (the decisions; the thread and the process exit are Dolphin glue) --------------------------------------------
constexpr int EXIT_CODE_FREEZE = 70;     // the freeze watchdog ended the process (LEAVE ... reason=freeze in the net log)
constexpr int EXIT_CODE_MAX_S = 71;      // REV3_NET_MAX_S ran out and the stop request did not end the process
constexpr int EXIT_CODE_STOP_HANG = 72;  // a planned stop was requested and the process did not end in STOP_GRACE_MS
constexpr int EXIT_CODE_LEFT = 73;       // the net session left unplanned (timeout, desync, lost link) and the run was stopped by REV3_NET_EXIT (LEAVE in the net log)
constexpr u32 STOP_GRACE_MS = 20000;     // how long a requested stop may take before the process is ended hard (milliseconds)

// Is this LEAVE reason one of a planned end? The session's reasons: "the peer left (<peer's BYE text>)" where the peer's text is its ExitController
// reason ("planned exit: ...") or "the emulator was closed". Everything else (timeouts, desync, HELLO mismatch, connection lost, ...) is unplanned.
// Our own planned exit never reaches this: it ends the session from Shutdown, after the last hook command.
bool IsPlannedLeaveReason(const std::string& why);

// REV3_NET_FREEZE_EXIT_S seconds after the freeze dump's stall limit with no hook command: `age_ms` = time since the last command, `stall_ms` = the
// dump's stall limit (REV3_SYNCTEST_DUMP_STALL_MS), `blocked` = the net session is deliberately waiting for the peer, `seen` = a command ever arrived.
bool FreezeExitDue(u64 age_ms, bool seen, bool blocked, u32 stall_ms, u32 exit_s);
// REV3_NET_MAX_S: elapsed wall milliseconds since the first hook command.
bool MaxSecondsDue(u64 elapsed_ms, u32 max_s);
// A requested stop that has not ended the process after STOP_GRACE_MS.
bool StopHangDue(u64 since_stop_ms);

// ---- options -----------------------------------------------------------------------------------------------------------------------
struct BotOptions
{
  bool bot = false;           // REV3_PAD_BOT set and valid
  u64 seed = 0;
  ExitSpec exit;              // REV3_NET_EXIT
  ExitTuning tuning;          // wait_calls from REV3_NET_EXIT_WAIT_S
  u32 freeze_exit_s = 0;      // REV3_NET_FREEZE_EXIT_S (0 = off)
  u32 max_s = 0;              // REV3_NET_MAX_S (0 = off)
  std::vector<std::string> warnings;  // variables set but unusable (that part is off / default)
  bool Any() const { return bot || exit.enabled || freeze_exit_s != 0 || max_s != 0; }
};
using GetEnvFn = std::function<std::string(const char*)>;  // "" for unset
BotOptions ParseBotOptions(const GetEnvFn& get_env);
}  // namespace Rev3::Bot
